49:    /**
50:     * Callback interface for Vehicle Map Service clients.
51:     */
52:    public interface VmsClientCallback {
53:        /**
54:         * Invoked when a Vehicle Map Service connection has been established for the callback.
55:         *
56:         * @param client API client
57:         */
58:        @AddedInOrBefore(majorVersion = 33)
