69:        /**
70:         * Invoked when any subscriptions to data layers have changed.
71:         *
72:         * @param subscriptionState Current subscription state
73:         */
74:        @AddedInOrBefore(majorVersion = 33)
75:        void onSubscriptionStateChanged(@NonNull VmsSubscriptionState subscriptionState);
76:
77:        /**
78:         * Invoked whenever a packet is received for this client's subscriptions.
79:         *
80:         * @param providerId  Packet provider
81:         * @param layer       Packet layer
82:         * @param packet      Packet data
83:         */
84:        @AddedInOrBefore(majorVersion = 33)
85:        void onPacketReceived(int providerId, @NonNull VmsLayer layer, @NonNull byte[] packet);
86:    }
87:
88:    private final IVmsBrokerService mBrokerService;
89:
90:    private final Object mLock = new Object();
91:    @GuardedBy("mLock")
92:    private final Map<VmsClientCallback, VmsClient> mClients = new ArrayMap<>();
