102:    /**
103:     * Registers new Vehicle Map Service client for the given callback.
104:     *
105:     * If the callback is already registered, no action is taken.
106:     *
107:     * @param executor Executor to run callback operations
108:     * @param callback Callback to register for new client
109:     */
110:    @RequiresPermission(anyOf = {Car.PERMISSION_VMS_PUBLISHER, Car.PERMISSION_VMS_SUBSCRIBER})
111:    @AddedInOrBefore(majorVersion = 33)
112:    public void registerVmsClientCallback(
113:            @NonNull @CallbackExecutor Executor executor,
114:            @NonNull VmsClientCallback callback) {
115:        registerVmsClientCallback(executor, callback, false);
116:    }
117:
118:    /**
119:     * @hide
120:     */
121:    @RequiresPermission(anyOf = {Car.PERMISSION_VMS_PUBLISHER, Car.PERMISSION_VMS_SUBSCRIBER})
122:    @AddedInOrBefore(majorVersion = 33)
123:    void registerVmsClientCallback(
124:            @NonNull @CallbackExecutor Executor executor,
125:            @NonNull VmsClientCallback callback,
126:            boolean legacyClient) {
127:        Objects.requireNonNull(executor, "executor cannot be null");
128:        Objects.requireNonNull(callback, "callback cannot be null");
129:        VmsClient client;
130:        synchronized (mLock) {
131:            if (mClients.containsKey(callback)) {
132:                Log.w(TAG, "VmsClient already registered");
133:                return;
134:            }
135:
136:            client = new VmsClient(mBrokerService, executor, callback, legacyClient,
137:                    /* autoCloseMemory */ true,
138:                    this::handleRemoteExceptionFromCarService);
139:            mClients.put(callback, client);
140:            if (DBG) Log.d(TAG, "Client count: " + mClients.size());
141:        }
142:
143:        try {
144:            if (DBG) Log.d(TAG, "Registering VmsClient");
145:            client.register();
146:        } catch (RemoteException e) {
147:            Log.e(TAG, "Error while registering", e);
148:            synchronized (mLock) {
149:                mClients.remove(callback);
150:            }
151:            handleRemoteExceptionFromCarService(e);
152:            return;
153:        }
154:
155:        if (DBG) Log.d(TAG, "Triggering callbacks for new VmsClient");
156:        executor.execute(() -> {
157:            callback.onClientConnected(client);
158:            if (!legacyClient) {
159:                callback.onLayerAvailabilityChanged(client.getAvailableLayers());
160:                callback.onSubscriptionStateChanged(client.getSubscriptionState());
161:            }
162:        });
163:    }
164:
165:    /**
166:     * Unregisters the Vehicle Map Service client associated with the given callback.
167:     *
168:     * If the callback is not registered, no action is taken.
169:     *
170:     * @param callback
171:     */
172:    @RequiresPermission(anyOf = {Car.PERMISSION_VMS_PUBLISHER, Car.PERMISSION_VMS_SUBSCRIBER})
173:    @AddedInOrBefore(majorVersion = 33)
174:    public void unregisterVmsClientCallback(@NonNull VmsClientCallback callback) {
175:        VmsClient client;
176:        synchronized (mLock) {
177:            client = mClients.remove(callback);
178:        }
179:        if (client == null) {
180:            Log.w(TAG, "Unregister called for unknown callback");
181:            return;
182:        }
183:
184:        if (DBG) Log.d(TAG, "Unregistering VmsClient");
185:        try {
186:            client.unregister();
187:        } catch (RemoteException e) {
188:            handleRemoteExceptionFromCarService(e);
189:        }
190:    }
191:
192:    /**
193:     * @hide
194:     */
195:    @Override
196:    @AddedInOrBefore(majorVersion = 33)
197:    protected void onCarDisconnected() {
198:        synchronized (mLock) {
199:            Log.w(TAG, "Car disconnected with " + mClients.size() + " active clients");
200:            mClients.clear();
201:        }
202:    }
