141:            assertTrue("Too slow. Expected to receive: " + EXPECTED_EVENTS
142:                            + " within " + WAIT_TIME + " ms, "
143:                            + " missing events per property: " + missingEventsPerProperty,
144:                    missingEventsPerProperty.size() == 0);
145:        }
146:    }
